{"code":"
fen = "rnbqkbnr/pp1p1ppp/2p5/1B2p3/4P3/8/PPPP1PPP/RNBQK1NR w KQkq - 0 3"
pos = simulate_move(fen)
cands = sorted(pos["legal_moves"])

def score_terminal(res):
    w = res.get("winner")
    if w == "white": return 100000
    if w == "black": return -100000
    return 0

def eval_pos(fen, side_to_move):
    p = simulate_move(fen)
    if p["game_over"]:
        return score_terminal(p)
    sq = p["squares"]
    vals = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0,
            'p':100,'n':320,'b':330,'r':500,'q':900,'k':0}
    mat = 0; cent = 0
    for s, ch in sq.items():
        val = vals[ch]
        if ch.isupper(): mat += val
        else: mat -= val
        if s in ('d4','e4','d5','e5'):
            if ch.isupper(): cent += 12
            else: cent -= 12
    score = mat + cent
    if p["in_check"]:
        if side_to_move == "white": score -= 25
        else: score += 25
    return score

results = {}
for mv in cands:
    after = simulate_move(fen, mv)
    if after["game_over"]:
        results[mv] = (score_terminal(after), None); print(mv, "TERM"); continue
    replies = sorted(after["legal_moves"])
    best_score = None; worst = None
    for rep in replies:
        rp = simulate_move(after["fen"], rep)
        if rp["game_over"]: s = score_terminal(rp)
        else: s = eval_pos(rp["fen"], "black")
        if best_score is None or s < best_score:
            best_score = s; worst = rep
    results[mv] = (best_score, worst)
    print(mv, best_score, worst)

best = max(cands, key=lambda m: results[m][0])
print("BEST:", best, results[best])
play_move(best)
"}

